-- CBMMG CFO BM 2027, Tipo A, itens 31–38.
-- Estado atual conferido pelo usuário em 2026-10-24: todos active; explicações existentes correspondem às pré-condições abaixo.
-- Atualiza apenas explicações/fontes e mantém active; NÃO cria vínculo ao edital nem altera syllabus_topic_id.
begin;
do $review$
declare
  r record; q public.board_exam_questions; before_row jsonb; after_row jsonb;
  a public.idecan_pedagogical_review_audit; batch text := 'idecan-cbmmg-itens31-38-explicacao-v2';
begin
  for r in (select * from (values
    ($id$7dfe5bfd-73a0-4de7-b9d3-2d6c35116971$id$::uuid, 31, $ans$D$ans$, $stem$A Declaração Universal dos Direitos Humanos, adotada pela Assembleia Geral das Nações Unidas em 10 de dezembro de 1948, constitui marco fundamental na consolidação da proteção internacional da dignidade da pessoa humana. À luz de suas disposições e de sua função no sistema internacional, assinale a alternativa que apresenta corretamente sua natureza e relevância.$stem$, $opt${"A": "Tratado internacional com força vinculante obrigatória aos Estados que participaram de sua aprovação.", "B": "Instrumento jurídico de aplicação facultativa, sem qualquer impacto na formação de normas internas dos Estados.", "C": "Norma regional aplicável exclusivamente aos países integrantes da Organização dos Estados Americanos.", "D": "Documento internacional que, embora não possua natureza de tratado, orienta a interpretação e a formulação de normas de direitos humanos."}$opt$::jsonb, $oldexp$A alternativa D está correta. A Declaração Universal de 1948 é uma resolução da Assembleia Geral da ONU, e não um tratado internacional ratificado pelos Estados. Mesmo sem a forma de tratado, tornou-se referência central para interpretar a dignidade humana e inspirar constituições, leis e tratados posteriores.$oldexp$, $exp$A alternativa D é a correta. A Declaração Universal dos Direitos Humanos (DUDH) foi proclamada pela Assembleia Geral da ONU em 1948 como declaração, não como tratado internacional. Ela enuncia um padrão comum de proteção e influenciou tratados, constituições e a interpretação dos direitos humanos. Isso não significa que suas disposições sejam juridicamente irrelevantes: algumas correspondem a normas consuetudinárias ou foram incorporadas em instrumentos vinculantes.

A) Incorreta: a DUDH não é, por si, tratado cuja força obrigatória decorra da ratificação. B) Incorreta: sua influência normativa e interpretativa é ampla. C) Incorreta: é universal, adotada no âmbito da ONU, não instrumento regional da OEA.

Base: preâmbulo e estrutura da DUDH; resolução 217 A (III) da Assembleia Geral da ONU. Gabarito definitivo IDECAN: D.$exp$, $src$["https://www.un.org/en/about-us/universal-declaration-of-human-rights", "https://www.ohchr.org/en/human-rights/universal-declaration/translations/portuguese"]$src$::jsonb),
    ($id$7ced0a3d-5659-43f8-8cd0-53f51e978b32$id$::uuid, 32, $ans$C$ans$, $stem$O Pacto Internacional dos Direitos Civis e Políticos estabelece garantias fundamentais relacionadas à liberdade individual e à proteção contra arbitrariedades estatais, constituindo instrumento central do sistema global de proteção dos direitos humanos. À luz de suas disposições, assinale a alternativa que reflete corretamente uma das garantias nele previstas.$stem$, $opt${"A": "Admissão de restrição da liberdade pessoal por mera conveniência administrativa, desde que prevista em ato estatal.", "B": "Autorização para suspensão geral e sem limites de direitos civis em toda hipótese de emergência nacional.", "C": "Proteção contra prisão ou detenção arbitrária, assegurado o direito de controle judicial da legalidade da detenção.", "D": "Subordinação integral dos direitos individuais ao direito interno, sem incidência de mecanismos internacionais de proteção."}$opt$::jsonb, $oldexp$A alternativa C está correta. O Pacto Internacional dos Direitos Civis e Políticos protege contra prisão ou detenção arbitrária e assegura que a pessoa privada de liberdade possa questionar judicialmente a legalidade da detenção. A emergência não autoriza suspensão ilimitada de direitos.$oldexp$, $exp$A alternativa C corresponde ao art. 9 do Pacto Internacional sobre Direitos Civis e Políticos (PIDCP): ninguém pode ser submetido a prisão ou detenção arbitrária; a pessoa presa deve ser informada dos motivos e pode levar a legalidade da custódia a um tribunal. O Pacto não proíbe toda prisão, mas exige fundamento legal, ausência de arbitrariedade e controle.

A) Incorreta: conveniência administrativa, isoladamente, não justifica privação arbitrária da liberdade. B) Incorreta: eventual derrogação em emergência é excepcional, limitada e sujeita às condições do art. 4; não há suspensão irrestrita. D) Incorreta: o Pacto cria obrigações internacionais para os Estados-partes.

Base: PIDCP, arts. 4 e 9, promulgado no Brasil pelo Decreto nº 592/1992. Gabarito definitivo IDECAN: C.$exp$, $src$["https://www.ohchr.org/en/instruments-mechanisms/instruments/international-covenant-civil-and-political-rights", "https://www.planalto.gov.br/ccivil_03/decreto/1990-1994/d0592.htm"]$src$::jsonb),
    ($id$472a03f7-e91e-4ad9-badb-18d5ba5389d5$id$::uuid, 33, $ans$C$ans$, $stem$No âmbito do sistema global de proteção aos direitos humanos, o Conselho de Direitos Humanos da ONU desempenha funções específicas relacionadas à promoção e ao monitoramento desses direitos. Considerando suas atribuições institucionais, assinale a alternativa que descreve corretamente uma competência do Conselho de Direitos Humanos.$stem$, $opt${"A": "Julgamento contencioso de violações individuais com decisões vinculantes aos Estados.", "B": "Fiscalização legislativa interna dos Estados-membros com poder de anulação de leis nacionais.", "C": "Realização de revisões periódicas universais sobre a situação de direitos humanos nos Estados.", "D": "Execução direta de sanções econômicas em casos de violações graves de direitos humanos."}$opt$::jsonb, $oldexp$A alternativa C está correta. O Conselho de Direitos Humanos da ONU realiza a Revisão Periódica Universal, mecanismo que examina a situação dos direitos humanos em todos os Estados-membros. Ele não funciona como tribunal para julgar individualmente violações nem anula leis nacionais.$oldexp$, $exp$A alternativa C descreve a Revisão Periódica Universal (RPU), mecanismo pelo qual a situação de direitos humanos de todos os Estados-membros da ONU é examinada periodicamente pelo Conselho de Direitos Humanos. A revisão se baseia, entre outros elementos, nas obrigações internacionais assumidas pelo Estado e em informações apresentadas por diferentes atores.

A) Incorreta: o Conselho não é corte para julgar casos individuais com decisões contenciosas vinculantes. B) Incorreta: não fiscaliza o processo legislativo nacional com poder de anular leis. D) Incorreta: não executa diretamente sanções econômicas; isso não é competência da RPU.

Base: Resolução 60/251 da Assembleia Geral da ONU e procedimento da RPU. Gabarito definitivo IDECAN: C.$exp$, $src$["https://www.ohchr.org/en/hr-bodies/upr/basic-facts", "https://www.ohchr.org/en/hr-bodies/hrc/about-council"]$src$::jsonb),
    ($id$c8e33e60-b292-4a8d-8e88-32956b1cfda1$id$::uuid, 34, $ans$A$ans$, $stem$Os direitos humanos constituem um conjunto de garantias reconhecidas historicamente, vinculadas à dignidade da pessoa humana e à limitação do poder estatal. Identifique a alternativa que expressa corretamente uma característica essencial dos direitos humanos.$stem$, $opt${"A": "Universalidade, com reconhecimento aplicável a todas as pessoas independentemente de condição.", "B": "Relatividade absoluta, permitindo sua restrição ilimitada pelos Estados.", "C": "Dependência exclusiva da legislação interna para sua existência jurídica.", "D": "Aplicação restrita a contextos culturais específicos previamente definidos."}$opt$::jsonb, $oldexp$A alternativa A está correta. A universalidade significa que os direitos humanos pertencem a todas as pessoas, sem discriminação por nacionalidade, origem, sexo, raça ou qualquer outra condição. Isso não impede limitações legais proporcionais em situações específicas.$oldexp$, $exp$A alternativa A está correta: universalidade significa que os direitos humanos pertencem a todas as pessoas, sem discriminação por nacionalidade, origem, condição ou outra situação. Universalidade não elimina debates sobre alcance e aplicação, nem torna todos os direitos absolutos; direitos podem admitir limites previstos em lei e compatíveis com os tratados, enquanto alguns são inderrogáveis.

B) Incorreta: relatividade não é absoluta nem autoriza restrição ilimitada. C) Incorreta: a proteção internacional não depende exclusivamente de lei interna. D) Incorreta: direitos humanos não se limitam a contextos culturais previamente escolhidos.

Base: Declaração e Programa de Ação de Viena (1993), § 5º. Gabarito definitivo IDECAN: A.$exp$, $src$["https://www.ohchr.org/en/what-are-human-rights/international-bill-human-rights"]$src$::jsonb),
    ($id$482329fd-f9c4-4a6d-aef8-13cb95b4ad82$id$::uuid, 35, $ans$B$ans$, $stem$A Convenção Americana sobre Direitos Humanos integra o sistema interamericano e estabelece mecanismos de proteção e responsabilização internacional dos Estados. Com base em suas disposições, identifique a alternativa correta.$stem$, $opt${"A": "Prevê apenas direitos econômicos e sociais, excluindo direitos civis e políticos.", "B": "Estabelece a competência da Corte Interamericana para julgar Estados que reconheçam sua jurisdição.", "C": "Limita sua aplicação exclusivamente a situações de conflito armado internacional.", "D": "Dispensa a necessidade de esgotamento de recursos internos para análise de casos individuais."}$opt$::jsonb, $oldexp$A alternativa B está correta. A Convenção Americana prevê a Corte Interamericana de Direitos Humanos e sua jurisdição contenciosa depende do reconhecimento pelo Estado. O tratado protege direitos civis e políticos e, em regra, exige o esgotamento dos recursos internos, salvo exceções.$oldexp$, $exp$A alternativa B é a correta no sentido do art. 62 da Convenção Americana sobre Direitos Humanos (CADH): a Corte Interamericana exerce jurisdição contenciosa sobre Estados-partes que reconheçam essa competência, nos termos e condições previstos no tratado. A Corte julga responsabilidade internacional do Estado; não julga pessoas como tribunal penal.

A) Incorreta: a CADH protege principalmente direitos civis e políticos e prevê também desenvolvimento progressivo em seu art. 26. C) Incorreta: sua aplicação não se limita a conflitos armados. D) Incorreta: petições à Comissão Interamericana em regra estão sujeitas ao esgotamento dos recursos internos, ressalvadas as exceções do art. 46(2).

Base: CADH, arts. 44, 46 e 62; promulgada no Brasil pelo Decreto nº 678/1992. Gabarito definitivo IDECAN: B.$exp$, $src$["https://www.oas.org/dil/treaties_b-32_american_convention_on_human_rights.htm", "https://www.planalto.gov.br/ccivil_03/decreto/d0678.htm"]$src$::jsonb),
    ($id$70087036-b55c-4304-bc60-5503af33aa95$id$::uuid, 36, $ans$D$ans$, $stem$Os direitos fundamentais previstos na Constituição Federal possuem eficácia e aplicabilidade que orientam a atuação estatal. Assinale a alternativa que expressa corretamente sua aplicabilidade.$stem$, $opt${"A": "Dependem integralmente de regulamentação infraconstitucional para produzir efeitos.", "B": "São restritos aos cidadãos brasileiros natos.", "C": "Aplicam-se exclusivamente às relações entre particulares.", "D": "Possuem aplicabilidade imediata, nos termos da Constituição."}$opt$::jsonb, $oldexp$A alternativa D está correta. O art. 5º, § 1º, da Constituição determina que as normas definidoras dos direitos e garantias fundamentais têm aplicação imediata. Isso não significa que toda regra dispense regulamentação, mas impede tratar os direitos como meras promessas sem eficácia.$oldexp$, $exp$A alternativa D reproduz o art. 5º, § 1º, da Constituição: as normas definidoras dos direitos e garantias fundamentais têm aplicação imediata. Isso orienta a interpretação e a atuação estatal; não quer dizer que todas as normas tenham idêntica estrutura ou que toda prestação prescinda de regulamentação para sua plena concretização.

A) Incorreta: nega a regra constitucional de aplicação imediata. B) Incorreta: o caput do art. 5º assegura direitos a brasileiros e estrangeiros residentes no País, sem prejuízo da interpretação jurisprudencial sobre proteção de outras pessoas sob jurisdição brasileira. C) Incorreta: direitos fundamentais também limitam e vinculam o Estado, não se restringindo às relações privadas.

Base: Constituição Federal, art. 5º, caput e § 1º. Gabarito definitivo IDECAN: D.$exp$, $src$["https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm"]$src$::jsonb),
    ($id$c0d42a5e-c8a2-4a69-b5fd-b1794a2be167$id$::uuid, 37, $ans$D$ans$, $stem$A sucessão de leis no tempo pode gerar situações em que uma norma revogada por lei posterior tenha sua revogadora posteriormente retirada do ordenamento jurídico. Nessa hipótese, discute-se a possibilidade de restauração automática da lei originariamente revogada. À luz da disciplina normativa aplicável, indique a alternativa correta.$stem$, $opt${"A": "A lei revogada readquire eficácia mediante interpretação judicial integrativa.", "B": "A lei revogada recupera automaticamente sua vigência com a perda de eficácia da lei revogadora.", "C": "A lei revogada retorna à vigência sempre que houver lacuna normativa relevante.", "D": "A lei revogada volta a vigorar somente se houver disposição expressa nesse sentido."}$opt$::jsonb, $oldexp$A alternativa D está correta. Pela regra da LINDB, a lei revogada não volta automaticamente a vigorar quando a lei revogadora perde eficácia. A repristinação somente ocorre se houver disposição expressa determinando o retorno da lei anterior.$oldexp$, $exp$A alternativa D aplica o art. 2º, § 3º, da LINDB: salvo disposição em contrário, a lei revogada não se restaura pelo fato de a lei revogadora perder vigência. Portanto, a repristinação não é automática; pode ocorrer se houver previsão expressa nesse sentido.

A), B) e C) estão erradas porque admitem retorno automático por interpretação judicial, perda de vigência da lei revogadora ou existência de lacuna. A regra exige disposição expressa em contrário.

Base: LINDB, art. 2º, § 3º. Gabarito definitivo IDECAN: D.$exp$, $src$["https://www.planalto.gov.br/ccivil_03/decreto-lei/del4657compilado.htm"]$src$::jsonb),
    ($id$b0880a41-4442-4564-b116-35266f3f7caa$id$::uuid, 38, $ans$A$ans$, $stem$No exercício da jurisdição, a ausência de previsão normativa específica não autoriza a abstenção do julgador, impondo a utilização de mecanismos jurídicos previamente estabelecidos para solução do caso concreto. Em determinada situação, reconhecida a omissão legislativa, o magistrado deve recorrer a instrumentos de integração normativa, observando os critérios legalmente previstos no ordenamento jurídico. Considerando essa disciplina, indique a alternativa que expressa corretamente os critérios aplicáveis à integração da norma em caso de omissão.$stem$, $opt${"A": "A solução deve observar a analogia como parâmetro, podendo ser complementada pelos costumes e pelos princípios gerais de direito.", "B": "A omissão legal autoriza a construção da decisão com base em precedentes vinculantes e regulamentos administrativos.", "C": "A integração normativa deve ser realizada com base na equidade e na interpretação extensiva, independentemente de outros critérios.", "D": "A decisão deve ser fundamentada prioritariamente na jurisprudência consolidada, seguida da doutrina majoritária e, subsidiariamente, na equidade."}$opt$::jsonb, $oldexp$A alternativa A está correta. Diante de lacuna, a Lei de Introdução às Normas do Direito Brasileiro orienta o julgador a decidir por analogia, costumes e princípios gerais de direito. Esses instrumentos integram o sistema e não autorizam o juiz a deixar de decidir.$oldexp$, $exp$A alternativa A reproduz a ordem de integração do art. 4º da LINDB: quando a lei for omissa, o juiz decidirá o caso de acordo com a analogia, os costumes e os princípios gerais de direito. O CPC, art. 140, também veda que o juiz deixe de decidir alegando lacuna ou obscuridade.

B) Incorreta: precedentes e regulamentos não substituem a sequência expressa do art. 4º como resposta geral à omissão. C) Incorreta: equidade e interpretação extensiva não são os critérios enumerados nesse dispositivo. D) Incorreta: jurisprudência e doutrina não aparecem nessa ordem legal de integração.

Base: LINDB, art. 4º; CPC, art. 140. Gabarito definitivo IDECAN: A.$exp$, $src$["https://www.planalto.gov.br/ccivil_03/decreto-lei/del4657compilado.htm", "https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2015/lei/l13105.htm"]$src$::jsonb)
  ) as v(id,item_number,answer,stem,options,old_explanation,new_explanation,sources)) loop
    select * into q from public.board_exam_questions where id=r.id for update;
    if not found then raise exception 'Questão CBMMG item % ausente; transação cancelada',r.item_number; end if;
    before_row := to_jsonb(q);
    select * into a from public.idecan_pedagogical_review_audit where batch_key=batch and question_id=q.id;
    if found then
      if before_row is distinct from a.after_data then raise exception 'Questão item % mudou após este lote; revisão posterior preservada',r.item_number; end if;
    else
      if q.board <> 'IDECAN' or q.contest_name <> 'CBMMG - CFO BM 2027 (Cadete BM) 2026'
        or q.exam_type <> 'Tipo A' or q.item_number <> r.item_number
        or q.official_answer <> r.answer or q.content_status <> 'active'
        or q.syllabus_topic_id is not null or q.stem <> r.stem or q.options <> r.options
        or q.explanation <> r.old_explanation
      then raise exception 'Questão %, estado ou conteúdo diverge da consulta enviada; nada será alterado',r.item_number; end if;
      update public.board_exam_questions set
        explanation=r.new_explanation,
        legal_basis=(select jsonb_agg(jsonb_build_object('title','Fonte oficial utilizada na revisão','url',value)) from jsonb_array_elements_text(r.sources)),
        legal_review_required=false,
        verified_at=now(),
        review_note='Explicação pedagógica ampliada e conferida com gabarito definitivo IDECAN e fontes oficiais indicadas em legal_basis. O status active foi preservado, sem alteração. syllabus_topic_id permanece nulo até validação e vínculo ao edital oficial desta edição.'
      where id=q.id returning to_jsonb(board_exam_questions) into after_row;
      insert into public.idecan_pedagogical_review_audit(batch_key,question_id,before_data,after_data,evidence,reviewer_id)
      values (batch,q.id,before_row,after_row,jsonb_build_object(
        'official_answer',r.answer,
        'official_answer_key_url','https://antigo-concurso.idecan.org.br/ConcursoDownloadArquivo.aspx?ID2=1&ID=GABARITO_OFICIAL_DEFINITIVO.pdf',
        'official_answer_key_sha256','e0ba9498205d7fb44682807f8476b017b9fb81b5b4458a70900ddb7165fae3b0',
        'sources',r.sources,'status_before','active','status_after','active',
        'syllabus_topic_id_before',null,'syllabus_topic_id_after',null,
        'syllabus_link_verified',false,'publication_status_changed',false),auth.uid());
    end if;
  end loop;
end
$review$;
commit;
select item_number,content_status,official_answer,explanation,syllabus_topic_id,legal_basis
from public.board_exam_questions where id in ($qid$7dfe5bfd-73a0-4de7-b9d3-2d6c35116971$qid$::uuid,$qid$7ced0a3d-5659-43f8-8cd0-53f51e978b32$qid$::uuid,$qid$472a03f7-e91e-4ad9-badb-18d5ba5389d5$qid$::uuid,$qid$c8e33e60-b292-4a8d-8e88-32956b1cfda1$qid$::uuid,$qid$482329fd-f9c4-4a6d-aef8-13cb95b4ad82$qid$::uuid,$qid$70087036-b55c-4304-bc60-5503af33aa95$qid$::uuid,$qid$c0d42a5e-c8a2-4a69-b5fd-b1794a2be167$qid$::uuid,$qid$b0880a41-4442-4564-b116-35266f3f7caa$qid$::uuid) order by item_number;
